'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const state={category:'all',sex:'all',collection:'all',q:'',sort:'category',page:1,favoritesOnly:false,tag:'all'};
const TAG_LABELS=['OK','PEÇA INCORRETA','DEFEITO NA TEXTURA'];
let tags={},tagLoad=null,detailTagsDirty=false,tagSaving=false;
const FAVORITES_KEY='acervo-favorites-v1';
let favorites=new Set();
try{const saved=JSON.parse(localStorage.getItem(FAVORITES_KEY)||'[]');if(Array.isArray(saved))favorites=new Set(saved.filter(id=>typeof id==='string'));}catch{}
function saveFavorite(id,checked){const next=new Set(favorites);if(checked)next.add(id);else next.delete(id);try{localStorage.setItem(FAVORITES_KEY,JSON.stringify([...next]));favorites=next;syncFavorites();return true;}catch{toast('Não foi possível salvar as favoritas neste navegador');return false;}}
let syncQueue=Promise.resolve();
function syncFavorites(){
 const ids=[...favorites];$('#sync-status').textContent='Sincronizando favoritas…';
 syncQueue=syncQueue.catch(()=>{}).then(async()=>{
  const response=await fetch('/api/favorites',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({ids})});
  if(!response.ok)throw Error('sync');
  const result=await response.json();$('#sync-status').textContent=`${result.count} favoritas salvas no acervo`;
 }).catch(()=>{$('#sync-status').textContent='Favoritas salvas no navegador. Sincronização com o jogo pendente.';});
 return syncQueue;
}
const PAGE_SIZE=24;let data,selected,lastFocused,toastTimer;
const sexLabel=s=>s==='male'?'Masculino':'Feminino';
const code=i=>`${i.category.toUpperCase()} ${String(i.index).padStart(3,'0')}`;
function el(tag,cls,text){const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e;}
function normalized(s){return s.toLocaleLowerCase('pt-BR').normalize('NFD').replace(/[\u0300-\u036f]/g,'');}
function filtered(){let rows=data.items.filter(i=>(!state.favoritesOnly||favorites.has(i.id))&&(state.tag==='all'||(state.tag==='untagged'?!(tags[i.id]||[]).length:(tags[i.id]||[]).includes(state.tag)))&&(state.category==='all'||i.category===state.category)&&(state.sex==='all'||i.sex===state.sex)&&(state.collection==='all'||i.collection===state.collection)&&normalized([i.title,i.collection,i.collectionLabel,i.file,i.index,sexLabel(i.sex)].join(' ')).includes(normalized(state.q)));if(state.sort==='textures')rows.sort((a,b)=>b.textureCount-a.textureCount);if(state.sort==='code')rows.sort((a,b)=>a.index-b.index);return rows;}
function update(reset=true){if(!data)return;if(reset)state.page=1;const rows=filtered(),pages=Math.max(1,Math.ceil(rows.length/PAGE_SIZE));state.page=Math.min(state.page,pages);$('#grid').replaceChildren();for(const i of rows.slice((state.page-1)*PAGE_SIZE,state.page*PAGE_SIZE)){
const card=el('article','card'),opener=el('button','card-open');opener.type='button';opener.setAttribute('aria-label',`${i.title}, ${code(i)}, ${sexLabel(i.sex)}. Ver detalhes`);
const pic=el('div','card-picture'),img=el('img');img.src=i.image;img.alt=`${i.title} ${String(i.index).padStart(3,'0')} — vista frontal`;img.loading='lazy';img.width=512;img.height=640;pic.append(img,el('span','sex-tag',sexLabel(i.sex)),el('span','open-tag','Ver peça'));
const info=el('div','card-info');info.append(el('p','card-label',i.title));const title=el('p','card-title',code(i));title.append(el('small','',`${i.textureCount} text.`));info.append(title);const bottom=el('div','card-bottom');bottom.append(el('span','card-collection',i.collectionLabel),el('span','',i.sex==='male'?'M':'F'));info.append(bottom);if((tags[i.id]||[]).length)info.append(el('p','review-tags',tags[i.id].join(' · ')));opener.append(pic,info);opener.addEventListener('click',()=>openDetail(i));const favorite=el('label','favorite-check'),check=el('input');check.type='checkbox';check.checked=favorites.has(i.id);check.setAttribute('aria-label',`Salvar como favorita: ${code(i)}, ${sexLabel(i.sex)}, ${i.collectionLabel}`);favorite.append(check,el('span','','Favorita'));check.addEventListener('change',()=>{if(!saveFavorite(i.id,check.checked)){check.checked=favorites.has(i.id);return;}if(state.favoritesOnly)update(false);});card.append(opener,favorite);$('#grid').append(card);}
$('#grid').setAttribute('aria-busy','false');$('#empty').hidden=!!rows.length;$('#count').textContent=`${rows.length} ${rows.length===1?'peça':'peças'}`;$('#current-category').textContent=(state.category==='all'?'Todas as peças':data.categories[state.category])+(state.favoritesOnly?' · Favoritas':'');$('#favorites-only').checked=state.favoritesOnly;$('#page-info').textContent=`${state.page} / ${pages}`;$('#prev').disabled=state.page===1;$('#next').disabled=state.page>=pages;$('.pagination').hidden=rows.length<=PAGE_SIZE;$('#clear').hidden=state.category==='all'&&state.sex==='all'&&state.collection==='all'&&!state.q&&!state.favoritesOnly&&state.tag==='all';
$$('.category').forEach(b=>b.setAttribute('aria-current',String(b.dataset.category===state.category)));$$('[data-sex]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.sex===state.sex)));$('#search').value=state.q;$('#collection').value=state.collection;$('#sort').value=state.sort;$('#tag-filter').value=state.tag;
}
function reset(){Object.assign(state,{category:'all',sex:'all',collection:'all',q:'',sort:'category',page:1,favoritesOnly:false,tag:'all'});update();}
function openDetail(i){selected=i;detailTagsDirty=false;lastFocused=document.activeElement;$('#detail-sex').textContent=`${sexLabel(i.sex).toUpperCase()} / ${i.title.toUpperCase()}`;$('#detail-title').textContent=code(i);$('#detail-collection').textContent=i.collectionLabel;$('#detail-facts').replaceChildren();for(const [name,value] of [['Categoria',i.title],['Arquivo',i.file],['Texturas encontradas',String(i.textureCount)],['Triângulos',i.triangles.toLocaleString('pt-BR')]]){const row=el('div','fact');row.append(el('dt','',name),el('dd','',value));$('#detail-facts').append(row);}$('#reference').textContent=`${i.sex==='male'?'mp_m_freemode_01':'mp_f_freemode_01'} | ${i.collection} | ${i.file} | ${i.textureFile}`;$('#texture-note').textContent=`Prévia da textura ${i.textureFile}. As demais variações ainda não estão nesta seleção.`;setView('front');renderDetailTags();$('#detail').showModal();}
async function loadTags(){
 if(tagLoad)return tagLoad;if(tagSaving)return false;
 tagLoad=(async()=>{
  const response=await fetch('/api/tags',{cache:'no-store'});if(!response.ok)throw Error('Não foi possível carregar as tags');
  const next=(await response.json()).items||{},changed=JSON.stringify(next)!==JSON.stringify(tags);tags=next;
  updateTagStatus();return changed;
 })();
 try{return await tagLoad;}finally{tagLoad=null;}
}
function updateTagStatus(){const approved=Object.values(tags).filter(values=>values.includes('OK')).length;$('#tags-sync-status').textContent=`Tags sincronizadas automaticamente · ${approved} peças OK no painel roupas`;}
async function syncTags(){if(!data||document.hidden)return;try{if(await loadTags()){update(false);if(!detailTagsDirty)renderDetailTags();}}catch{$('#tags-sync-status').textContent='Sincronização das tags pendente. Confira se o acervo está iniciado.';}}
setInterval(syncTags,3000);
window.addEventListener('focus',syncTags);
document.addEventListener('visibilitychange',syncTags);
function renderDetailTags(){if(!selected)return;$('#detail-tags').replaceChildren();for(const tag of TAG_LABELS){const label=el('label'),check=el('input');check.type='checkbox';check.checked=(tags[selected.id]||[]).includes(tag);check.value=tag;check.onchange=()=>{detailTagsDirty=true;if(check.checked)for(const other of $('#detail-tags').querySelectorAll('input'))if(other!==check&&(tag==='OK'||other.value==='OK'))other.checked=false;};label.append(check,el('span','',tag));$('#detail-tags').append(label);}}
$('#tag-filter').onchange=()=>{state.tag=$('#tag-filter').value;update();};
$('#refresh-tags').onclick=async()=>{try{await loadTags();update(false);if(!detailTagsDirty)renderDetailTags();toast('Tags atualizadas do jogo');}catch(error){toast(error.message);}};
$('#save-tags').onclick=async()=>{if(!selected)return;const itemId=selected.id,values=[...$('#detail-tags').querySelectorAll('input:checked')].map(i=>i.value);$('#save-tags').disabled=true;tagSaving=true;try{if(tagLoad)await tagLoad;const response=await fetch('/api/tags',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:itemId,tags:values})}),result=await response.json();if(!response.ok)throw Error(result.error);if(result.tags.length)tags[itemId]=result.tags;else delete tags[itemId];if(selected?.id===itemId)detailTagsDirty=false;update(false);updateTagStatus();toast('Tags salvas no acervo');}catch(error){toast(error.message);}finally{tagSaving=false;$('#save-tags').disabled=false;}};

function setView(view){if(!selected)return;$('#detail-image').src=view==='front'?selected.image:selected.back;$('#detail-image').alt=`${selected.title} ${code(selected)} — ${view==='front'?'frente':'costas'}`;$$('[data-view]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.view===view)));}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2500);}
$('#sync-favorites').addEventListener('click',()=>syncFavorites());
$('#favorites-only').addEventListener('change',e=>{state.favoritesOnly=e.target.checked;update();});
window.addEventListener('storage',e=>{if(e.key!==FAVORITES_KEY&&e.key!==null)return;try{const saved=JSON.parse(e.newValue||'[]');favorites=new Set(Array.isArray(saved)?saved.filter(id=>typeof id==='string'):[]);update(false);}catch{}});
$$('[data-sex]').forEach(b=>b.addEventListener('click',()=>{state.sex=b.dataset.sex;update();}));$('#search').addEventListener('input',e=>{state.q=e.target.value;update();});$('#collection').addEventListener('change',e=>{state.collection=e.target.value;update();});$('#sort').addEventListener('change',e=>{state.sort=e.target.value;update();});$('#clear').onclick=reset;$('#reset-empty').onclick=reset;$('#prev').onclick=()=>{state.page--;update(false);$('.results-heading').scrollIntoView({block:'start',behavior:'smooth'});};$('#next').onclick=()=>{state.page++;update(false);$('.results-heading').scrollIntoView({block:'start',behavior:'smooth'});};$$('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));$$('dialog .close').forEach(b=>b.onclick=()=>b.closest('dialog').close());$$('dialog').forEach(d=>{d.addEventListener('click',e=>{const r=d.getBoundingClientRect();if(e.target===d&&(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom))d.close();});d.addEventListener('close',()=>lastFocused?.focus());});$('#about-button').onclick=()=>{lastFocused=document.activeElement;$('#about').showModal();};$('#copy').onclick=async()=>{try{await navigator.clipboard.writeText($('#reference').textContent);toast('Referência copiada');}catch{const range=document.createRange();range.selectNodeContents($('#reference'));getSelection().removeAllRanges();getSelection().addRange(range);toast('Selecione e copie a referência acima');}};document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!$('dialog[open]')){e.preventDefault();$('#search').focus();}});
async function init(){try{const response=await fetch('catalog.json',{cache:'no-store'});if(!response.ok)throw Error('catalog');data=await response.json();$('#catalog-summary').textContent=`${data.items.length.toLocaleString('pt-BR')} modelos masculinos e femininos nas ${Object.keys(data.categories).length} categorias do acervo. Incluímos todas as peças renderizáveis com malha e textura encontradas no inventário local. Cada categoria mostra a quantidade disponível no menu lateral.`;for(const i of data.items){if(i.collection.includes("freemode_01_p"))i.collectionLabel=(i.collectionLabel==="p"?"Jogo base":i.collectionLabel)+" · acessórios";}const addCategory=(id,label,count)=>{const b=el('button','category');b.dataset.category=id;b.append(el('span','',label),el('small','',String(count)));b.onclick=()=>{state.category=id;state.collection='all';update();};$('#categories').append(b);};addCategory('all','Todas as peças',data.items.length);for(const [id,label] of Object.entries(data.categories))addCategory(id,label,data.items.filter(i=>i.category===id).length);const collections=new Map(data.items.map(i=>[i.collection,`${i.collectionLabel} · ${i.sex==='male'?'M':'F'}`]));for(const [value,label] of [...collections].sort((a,b)=>a[1].localeCompare(b[1]))){const option=el('option','',label);option.value=value;$('#collection').append(option);}update();
 const savedResponse=await fetch('/api/favorites',{cache:'no-store'});const saved=savedResponse.ok?await savedResponse.json():{ids:[]};
 if(savedResponse.ok&&!favorites.size){if(Array.isArray(saved.ids)&&saved.ids.length){favorites=new Set(saved.ids.filter(id=>data.items.some(i=>i.id===id)));localStorage.setItem(FAVORITES_KEY,JSON.stringify([...favorites]));update();}}
 await loadTags();update(false);
 if(savedResponse.ok){const remote=new Set(saved.ids||[]);const matches=remote.size===favorites.size&&[...favorites].every(id=>remote.has(id));$('#sync-status').textContent=matches?`${remote.size} favoritas salvas no acervo`:`${favorites.size} favoritas neste navegador; ${remote.size} salvas no acervo. Clique em Sincronizar favoritas.`;}registerTools();}catch(error){$('#error').hidden=false;$('#count').textContent='Acervo indisponível';$('#grid').setAttribute('aria-busy','false');$('.pagination').hidden=true;console.error(error);}}
function registerTools(){const context=document.modelContext;if(!context?.registerTool)return;try{Promise.resolve(context.registerTool({name:'filter_clothing_catalog',title:'Filtrar peças do catálogo',description:'Aplica os filtros visíveis de categoria, personagem e busca e retorna as peças encontradas.',inputSchema:{type:'object',properties:{category:{type:'string',enum:['all',...Object.keys(data.categories)]},sex:{type:'string',enum:['all','male','female']},query:{type:'string'}},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input!=='object'||Object.keys(input).some(k=>!['category','sex','query'].includes(k))||(input.category!==undefined&&!['all',...Object.keys(data.categories)].includes(input.category))||(input.sex!==undefined&&!['all','male','female'].includes(input.sex))||(input.query!==undefined&&typeof input.query!=='string'))throw Error('Filtros inválidos');Object.assign(state,{category:input.category??'all',sex:input.sex??'all',q:input.query??'',collection:'all',tag:'all'});update();return{count:filtered().length,items:filtered().slice(0,24).map(i=>({id:i.id,category:i.title,file:i.file,sex:i.sex,collection:i.collection}))};}})).catch(()=>{});}catch{}}
init();
